// Plain text only: external mail is hostile (CLAUDE.md rule 11).
const MAX_TEXT = 8000;
return $input.all().map(({ json }) => {
  const from = String(json.from ?? '').toLowerCase();
  const subject = String(json.subject ?? '');
  let origin = 'correo';
  if (/wix/.test(from) || /wix/i.test(subject)) origin = 'formulario';
  else if (/chatonbo/.test(from) || /chatonbo/i.test(subject)) origin = 'bot';
  const text = String(json.textPlain ?? '').slice(0, MAX_TEXT);
  return { json: { message_id: json.messageId ?? json['message-id'] ?? null, from, subject, origin, text } };
});

// The classifier only classifies: anything off-schema becomes 'indeterminada'.
const LINES = ['valvulas', 'tuberias', 'geoceldas', 'indeterminada'];
const source = $('Detectar origen y extraer texto').all();
return $input.all().map(({ json }, i) => {
  let out = null;
  try { out = JSON.parse(json.content?.[0]?.text ?? ''); } catch {}
  const valid = out && LINES.includes(out.linea) && typeof out.confianza === 'number' && out.confianza >= 0 && out.confianza <= 1 && typeof out.es_spam === 'boolean';
  const str = (v, max) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
  const ai = valid
    ? { linea: out.linea, confianza: out.confianza, es_spam: out.es_spam, empresa: str(out.empresa, 200), nombre: str(out.nombre, 200), correo: str(out.correo, 254), telefono: str(out.telefono, 20), necesidad: str(out.necesidad, 200) }
    : { linea: 'indeterminada', confianza: 0, es_spam: false, invalid_ai_output: true };
  return { json: { ...source[i].json, ai } };
});
